use harness_strategy_sdk::{export_strategy_program, BarFrame, MarketConsumer, OrderSink, StrategyProgram, Subscription};
use harness_strategy_sdk::serde_json::Value;

const ENTRY_BAND: f64 = 0.9;

struct MomentumBreakout {
    threshold: f64,
}

impl MarketConsumer for MomentumBreakout {
    type Context = OrderSink;

    fn subscriptions(&self) -> Vec<Subscription> {
        vec![Subscription::Bars { symbols: vec!["SPY".into()], interval: "1min".into() }]
    }

    fn on_bar(&mut self, frame: &BarFrame, orders: &mut OrderSink) {
        let Some(bar) = frame.bars_by_symbol.get("SPY") else { return };
        if bar.close > bar.open * (1.0 + self.threshold) {
            orders.submit_market_buy("SPY");
        }
    }
}

impl StrategyProgram for MomentumBreakout {
    fn new(parameters: Value) -> Self {
        Self { threshold: parameters["threshold"].as_f64().unwrap_or(ENTRY_BAND) }
    }
}

export_strategy_program!(MomentumBreakout);

