use harness_strategy_sdk::{export_study_program, BarFrame, MarketConsumer, MetricPublisher, ObservationContext, StudyProgram, Subscription};
use harness_strategy_sdk::serde_json::Value;

#[derive(Default)]
struct BreakoutThresholds {
    frames: u64,
    breaches: u64,
}

impl MarketConsumer for BreakoutThresholds {
    type Context = ObservationContext;

    fn subscriptions(&self) -> Vec<Subscription> {
        vec![Subscription::Bars { symbols: vec!["SPY".into()], interval: "1min".into() }]
    }

    fn on_bar(&mut self, frame: &BarFrame, _: &mut ObservationContext) {
        self.frames += 1;
        if let Some(bar) = frame.bars_by_symbol.get("SPY") {
            if bar.close > bar.open * 1.009 {
                self.breaches += 1;
            }
        }
    }
}

impl StudyProgram for BreakoutThresholds {
    fn new(_: Value) -> Self { Self::default() }

    fn on_stop(&mut self, metrics: &mut MetricPublisher) {
        let _ = metrics.publish("frames", self.frames as f64);
        let _ = metrics.publish("breaches", self.breaches as f64);
    }
}

export_study_program!(BreakoutThresholds);

