use harness_strategy_sdk::{BarFrame, Decimal, Indicator, MarketConsumer, ObservationContext, Subscription};

#[derive(Default)]
pub struct RsiValue {
    last: Option<Decimal>,
    gains: Decimal,
    losses: Decimal,
}

impl MarketConsumer for RsiValue {
    type Context = ObservationContext;

    fn subscriptions(&self) -> Vec<Subscription> {
        vec![Subscription::Bars { symbols: vec!["SPY".into()], interval: "1min".into() }]
    }

    fn on_bar(&mut self, frame: &BarFrame, _: &mut ObservationContext) {
        let Some(bar) = frame.bars_by_symbol.get("SPY") else { return };
        let change = bar.close - bar.open;
        if change > Decimal::ZERO {
            self.gains += change;
        } else {
            self.losses -= change;
        }
        self.last = Some(bar.close);
    }
}

impl Indicator for RsiValue {
    fn value(&self) -> Option<Decimal> { self.last }
}

