use harness_strategy_sdk::{export_study_program, MarketConsumer, MetricPublisher, ObservationContext, StudyProgram, Subscription, TradeEvent};
use harness_strategy_sdk::serde_json::Value;

#[derive(Default)]
struct CarryFit {
    trades: u64,
    notional: f64,
}

impl MarketConsumer for CarryFit {
    type Context = ObservationContext;

    fn subscriptions(&self) -> Vec<Subscription> {
        vec![Subscription::Trade { symbols: vec!["TLT".into()] }]
    }

    fn on_trade(&mut self, trade: &TradeEvent, _: &mut ObservationContext) {
        self.trades += 1;
        self.notional += trade.notional().to_f64().unwrap_or_default();
    }
}

impl StudyProgram for CarryFit {
    fn new(_: Value) -> Self { Self::default() }

    fn on_stop(&mut self, metrics: &mut MetricPublisher) {
        let _ = metrics.publish("trades", self.trades as f64);
        let _ = metrics.publish("notional", self.notional);
    }
}

export_study_program!(CarryFit);

